<?php declare(strict_types=1); namespace Modules\PromptEngine\Services\ImageProviders; use Illuminate\Support\Facades\Http; use RuntimeException; use Modules\PromptEngine\Interfaces\ImageGenerationProviderInterface; final class ChatGptImageProvider implements ImageGenerationProviderInterface { public function name():string{return 'chatgpt-image';} public function generate(string $prompt,string $aspectRatio):array{$cfg=config('promptengine.config.image_generation');if(empty($cfg['chatgpt-image']['api_key']))throw new RuntimeException('ChatGPT Image provider is not configured.');$size=in_array($aspectRatio,['16:9'],true)?'1536x1024':(in_array($aspectRatio,['1:1'],true)?'1024x1024':'1024x1536');$response=Http::timeout($cfg['timeout'])->retry($cfg['retries'],300)->withToken($cfg['chatgpt-image']['api_key'])->post('https://api.openai.com/v1/images/generations',['model'=>$cfg['chatgpt-image']['model'],'prompt'=>$prompt,'size'=>$size]);$response->throw();$encoded=$response->json('data.0.b64_json');if(!is_string($encoded))throw new RuntimeException('OpenAI returned no image data.');return ['bytes'=>base64_decode($encoded,true),'mime_type'=>'image/png'];} }
